function fewestPasses(s: string): number {
  const n = s.length;
  const memo = new Map<number, number>();
  const f = (i: number, j: number): number => {
    if (i > j) return 0;
    const key = i * 128 + j;
    if (memo.has(key)) return memo.get(key)!;
    let best = 1 + f(i + 1, j);
    for (let k = i + 1; k <= j; k++) {
      if (s[k] === s[i]) best = Math.min(best, f(i + 1, k - 1) + f(k, j));
    }
    memo.set(key, best);
    return best;
  };
  return f(0, n - 1);
}

