class Solution:
    def fewestPasses(self, s: str) -> int:
        t = []
        for ch in s:
            if not t or t[-1] != ch:
                t.append(ch)
        n = len(t)
        dp = [[0] * n for _ in range(n)]
        for i in range(n - 1, -1, -1):
            dp[i][i] = 1
            for j in range(i + 1, n):
                best = dp[i][j - 1] + 1
                for k in range(i, j):
                    if t[k] == t[j]:
                        inner = dp[k + 1][j - 1] if k + 1 <= j - 1 else 0
                        best = min(best, dp[i][k] + inner)
                dp[i][j] = best
        return dp[0][n - 1]

